MonarchAiMarkdown(
    text = "```mermaid\ngraph TD; A-->B\n```",
    codeBlock = { language, code, complete ->
        if (language == "mermaid") {
            MonarchText(text = "Diagram: $code")
        } else {
            MonarchCodeBlock(code = code, language = language.ifEmpty { null }, copyable = complete)
        }
    },
)
